import {join,resolve,dirname,isAbsolute} from 'node:path';
import {fileURLToPath} from 'node:url';
import {randomUUID} from 'node:crypto';
import {unlink,chmod} from 'node:fs/promises';
import {ResearchWorkspaceClient} from './workspace-client.mjs';
import {readResearchHostFile} from './workspace-files.mjs';
import {digest,jsonBytes,need,privateDirectory} from '../node/store.mjs';
import {STUDY_PROTOCOL_SCHEMA,STUDY_PROTOCOL_REGISTRY,inspectStudyProtocolCapture,
  protocolOptional,protocolImmutable,protocolImmutableJson} from './study-protocol-source.mjs';

const MAX=256*1024*1024;
export const STUDY_PROTOCOL_PROGRAM_FILES=Object.freeze([
  'study-protocol-source.mjs','study-protocol-methods.mjs','study-protocol-receiving.mjs',
  'study-protocol-cli.mjs','package-study-protocol.py','STUDY-PROTOCOL-RECEIVING.md'
]);
const selectedFile=(file,bytes)=>({file,bytes:bytes.length,sha256:digest(bytes)});
async function completeFile(root,entry){
  need(typeof entry.file==='string'&&!entry.file.startsWith('/')&&
    entry.file.split('/').every(part=>part&&part!=='.'&&part!=='..')&&!entry.file.includes('\\'),
    'PROTOCOL_DELIVERY_MEMBER_INVALID');
  const bytes=await readResearchHostFile(join(root,entry.file),MAX,{sha256:entry.sha256});
  need(bytes.length===entry.bytes,'PROTOCOL_DELIVERY_MEMBER_CHANGED');
  return bytes;
}
export async function inspectStudyProtocolReceiving(directory){
  const root=resolve(directory),raw=await readResearchHostFile(join(root,'RECEIVING_COMPLETE.json'),4*1024*1024);
  const result=JSON.parse(raw.toString('utf8'));
  need(result.schema===STUDY_PROTOCOL_SCHEMA&&result.state==='RECEIVED_AND_EXPORTED'&&
    Array.isArray(result.files),'PROTOCOL_RECEIVING_REQUIRED');
  for(const entry of result.files)await completeFile(root,entry);
  return result;
}
async function exportFile(root,name,invoke,{expectedSha256}={}){
  const receiptFile=join(root,'records','export-'+name.replaceAll('/','__')+'.json');
  const saved=await protocolOptional(receiptFile,1024*1024);
  if(saved){
    const record=JSON.parse(saved.toString('utf8'));
    need(record.file===name&&(!expectedSha256||record.sha256===expectedSha256),'PROTOCOL_EXPORT_SELECTION_CHANGED');
    await completeFile(root,record);return record;
  }
  const temporary=join(root,'.export-'+randomUUID());
  try{
    const response=await invoke(temporary);
    const bytes=await readResearchHostFile(temporary,MAX,expectedSha256?{sha256:expectedSha256}:{});
    need(response?.bytes===bytes.length&&response?.sha256===digest(bytes),'PROTOCOL_EXPORT_RESPONSE_CHANGED');
    const file=join(root,...name.split('/'));
    await privateDirectory(dirname(file));
    await protocolImmutable(file,bytes);
    const record={...selectedFile(name,bytes),response};
    await protocolImmutableJson(receiptFile,record);return record;
  }finally{await unlink(temporary).catch(error=>{if(error.code!=='ENOENT')throw error;});}
}
