async function selectEngineCohort(root,engineSourceFile){
  const selectionName='records/engine-selection.json';
  const saved=await protocolOptional(join(root,selectionName),16*1024*1024);
  let supplied=null;
  if(engineSourceFile!==undefined){
    need(typeof engineSourceFile==='string'&&isAbsolute(engineSourceFile)&&
      resolve(engineSourceFile)===engineSourceFile,'PROTOCOL_ENGINE_SELECTION_FILE_REQUIRED');
    supplied=await readResearchHostFile(engineSourceFile,16*1024*1024);
  }
  if(saved&&supplied)need(saved.equals(supplied),'PROTOCOL_ENGINE_SELECTION_CHANGED');
  const raw=supplied??saved;
  if(!raw)return {cohort:ORIGINAL_ENGINE_COHORT,selection:null,raw:null};
  const cohort=JSON.parse(raw.toString('utf8'));
  need(cohort&&typeof cohort==='object'&&!Array.isArray(cohort)&&
    typeof cohort.id==='string'&&/^[A-Za-z0-9][A-Za-z0-9_.:-]{0,255}$/.test(cohort.id)&&
    typeof cohort.repository==='string'&&/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(cohort.repository)&&
    typeof cohort.ref==='string'&&/^[a-f0-9]{40}$/.test(cohort.ref)&&
    Array.isArray(cohort.files)&&cohort.files.length>0,'PROTOCOL_ENGINE_COHORT_REQUIRED');
  const paths=new Set();let sourceBytes=0;
  for(const row of cohort.files){
    need(row&&typeof row==='object'&&!Array.isArray(row)&&typeof row.path==='string'&&
      !row.path.startsWith('/')&&!row.path.includes('\\')&&!row.path.includes('\0')&&
      row.path.split('/').every(part=>part&&part!=='.'&&part!=='..')&&!paths.has(row.path),
      'PROTOCOL_ENGINE_SOURCE_PATH_INVALID');
    need(Number.isSafeInteger(row.bytes)&&row.bytes>=0&&row.bytes<=MAX&&
      typeof row.sha256==='string'&&/^[a-f0-9]{64}$/.test(row.sha256)&&
      ['100644','100755'].includes(row.mode),'PROTOCOL_ENGINE_SOURCE_DESCRIPTOR_INVALID');
    paths.add(row.path);sourceBytes+=row.bytes;
  }
  need(Number.isSafeInteger(sourceBytes)&&cohort.baseFiles===cohort.files.length&&
    cohort.baseBytes===sourceBytes,'PROTOCOL_ENGINE_COHORT_INVENTORY_CHANGED');
  need(ORIGINAL_ENGINE_COHORT.files.every(row=>paths.has(row.path)),
    'PROTOCOL_ENGINE_COHORT_INCOMPLETE');
  return {cohort,selection:selectedFile(selectionName,raw),raw};
}

async function copyProgramSource(root,chosen){
  const {cohort,selection,raw:selectionRaw}=chosen;
  const programmeRoot=dirname(fileURLToPath(import.meta.url));
  const repositoryRoot=resolve(programmeRoot,'../../../..');
  need(join(repositoryRoot,PROGRAMME_PREFIX)===programmeRoot,'PROTOCOL_SOURCE_LAYOUT_CHANGED');
  const files=[],engineFiles=[],overrides=[],seen=new Set();
  await privateDirectory(join(root,'programme-source'));
  await privateDirectory(join(root,'engine-source'));
  if(selection){
    await protocolImmutable(join(root,selection.file),selectionRaw);
    files.push(selection);
  }
  async function copyEngineFile(row,bytes){
    need(typeof row.path==='string'&&row.path.split('/').every(part=>part&&part!=='.'&&part!=='..')&&
      !row.path.includes('\\')&&!seen.has(row.path),'PROTOCOL_ENGINE_SOURCE_PATH_INVALID');
    need(['100644','100755'].includes(row.mode),'PROTOCOL_ENGINE_SOURCE_MODE_INVALID');
    need(bytes.length===row.bytes&&digest(bytes)===row.sha256,'PROTOCOL_ENGINE_SOURCE_CHANGED');
    seen.add(row.path);
    const output='engine-source/'+row.path;
    await privateDirectory(dirname(join(root,output)));
    await protocolImmutable(join(root,output),bytes);
    if(row.mode==='100755')await chmod(join(root,output),0o700);
    files.push(selectedFile(output,bytes));engineFiles.push({...row});
  }
  for(const row of cohort.files){
    const bytes=await readResearchHostFile(join(repositoryRoot,row.path),MAX,{sha256:row.sha256});
    await copyEngineFile(row,bytes);
  }
  need(engineFiles.length===cohort.baseFiles&&
    engineFiles.reduce((total,row)=>total+row.bytes,0)===cohort.baseBytes&&
    seen.has('LICENSE'),'PROTOCOL_ORIGINAL_ENGINE_INCOMPLETE');
  for(const name of STUDY_PROTOCOL_PROGRAM_FILES){
    const bytes=await readResearchHostFile(join(programmeRoot,name),4*1024*1024);
    const row={path:PROGRAMME_PREFIX+'/'+name,bytes:bytes.length,sha256:digest(bytes),mode:'100644'};
    const existing=engineFiles.find(item=>item.path===row.path);
    if(existing){
      need(existing.bytes===row.bytes&&existing.sha256===row.sha256,
        'PROTOCOL_ENGINE_PROGRAMME_CHANGED');
      overrides.push({...existing});
    }else{await copyEngineFile(row,bytes);overrides.push(row);}
    const output='programme-source/'+name;
    await protocolImmutable(join(root,output),bytes);files.push(selectedFile(output,bytes));
  }
  const {files:originalFiles,...sourceCohort}=cohort;
  const manifest={schema:'sf88-study-protocol-engine-source/v1',engineRoot:'engine-source',
    repository:cohort.repository,ref:cohort.ref,sourceCohort,
    ...(selection?{engineSelection:selection}:{}),
    overlays:overrides,files:engineFiles,sourceFiles:engineFiles.length,
    sourceBytes:engineFiles.reduce((total,row)=>total+row.bytes,0)};
  const expectedPaths=new Set([...originalFiles.map(row=>row.path),
    ...STUDY_PROTOCOL_PROGRAM_FILES.map(name=>PROGRAMME_PREFIX+'/'+name)]);
  need(manifest.sourceFiles===expectedPaths.size&&overrides.length===6,
    'PROTOCOL_ENGINE_DELIVERY_INCOMPLETE');
  const raw=jsonBytes(manifest);await protocolImmutable(join(root,'ENGINE_SOURCE.json'),raw);
  files.push(selectedFile('ENGINE_SOURCE.json',raw));
  return {files,engineSelection:selection};
}
export async function receiveStudyProtocol({
  captureDirectory,directory,connectionFile,client:providedClient,expectedWorkspaceId,
  dossierId,questionId,baseRevision,engineSourceFile,
  operation='DBC61-SCF-STUDY-EXTRACTION-20261012-PROTOCOL'
}){
  need(typeof directory==='string'&&isAbsolute(directory)&&resolve(directory)===directory,'PROTOCOL_ABSOLUTE_DIRECTORY_REQUIRED');
  need(typeof expectedWorkspaceId==='string'&&/^research_[a-f0-9]{64}$/.test(expectedWorkspaceId),'PROTOCOL_WORKSPACE_REQUIRED');
  need(typeof dossierId==='string'&&typeof questionId==='string'&&
    Number.isSafeInteger(baseRevision)&&baseRevision>=1,'PROTOCOL_ORIGINAL_QUESTION_REQUIRED');
  need(typeof operation==='string'&&/^[A-Za-z0-9][A-Za-z0-9_.-]{0,159}$/.test(operation),'PROTOCOL_OPERATION_REQUIRED');
  need(Boolean(providedClient)!==Boolean(connectionFile),'PROTOCOL_ONE_ORIGINAL_CLIENT_REQUIRED');
  const root=await privateDirectory(directory);
  await privateDirectory(join(root,'records'));
  await privateDirectory(join(root,'original-source'));
  const chosenEngine=await selectEngineCohort(root,engineSourceFile);
  const capture=await inspectStudyProtocolCapture(resolve(captureDirectory));
  need(capture.complete.operation===operation&&capture.complete.registry.sha256===STUDY_PROTOCOL_REGISTRY.sha256,
    'PROTOCOL_CAPTURE_OPERATION_CHANGED');
  const intent={schema:STUDY_PROTOCOL_SCHEMA,operation,workspaceId:expectedWorkspaceId,dossierId,questionId,baseRevision,
    bundleSha256:capture.complete.bundleSha256,bundleBytes:capture.complete.bundleBytes,
    registrySha256:capture.complete.registry.sha256,protocolSha256:capture.complete.protocol.sha256};
  await protocolImmutableJson(join(root,'receiving-selection.json'),intent);
  if(await protocolOptional(join(root,'RECEIVING_COMPLETE.json'),4*1024*1024)){
    const done=await inspectStudyProtocolReceiving(root);
    need(done.operation===operation&&done.bundleSha256===intent.bundleSha256&&
      done.workspaceId===expectedWorkspaceId&&done.dossierId===dossierId&&done.questionId===questionId,
      'PROTOCOL_RECEIVING_SELECTION_CHANGED');
    if(chosenEngine.selection)need(done.engineSelection?.sha256===chosenEngine.selection.sha256&&
      done.engineSelection?.bytes===chosenEngine.selection.bytes,'PROTOCOL_ENGINE_SELECTION_CHANGED');
    return done;
  }
  const programme=await copyProgramSource(root,chosenEngine);
  const programmeFiles=programme.files;
  const client=providedClient??new ResearchWorkspaceClient({connectionFile:resolve(connectionFile),expectedWorkspaceId});
  try{
    const status=await client.status();
    need(status.workspaceId===expectedWorkspaceId,'PROTOCOL_WORKSPACE_CHANGED');
    const baseline=await client.metadata(dossierId,{revision:baseRevision});
    need(baseline.id===dossierId&&baseline.revision===baseRevision&&
      baseline.questions.some(question=>question.id===questionId),'PROTOCOL_BASE_QUESTION_CHANGED');
    await protocolImmutableJson(join(root,'records','baseline.json'),baseline);
    const savedReceive=await protocolOptional(join(root,'records','received.json'),16*1024*1024);
    let received;
    if(savedReceive){
      received=JSON.parse(savedReceive.toString('utf8'));
    }else{
      // Preview supplies the current revision for this additive native operation.
      // The original store recovers the exact same bundle after a lost response.
      const preview=await client.previewSourceBundleBytes(dossierId,{questionId,bytes:capture.bundle});
      need(preview.bundleSha256===intent.bundleSha256&&preview.bundleBytes===intent.bundleBytes&&
        preview.dossierId===dossierId&&preview.questionId===questionId&&
        Number.isSafeInteger(preview.expectedRevision)&&preview.expectedRevision>=baseRevision,
        'PROTOCOL_NATIVE_PREVIEW_CHANGED');
      const previewFile=join(root,'records','preview-'+preview.expectedRevision+'.json');
      await protocolImmutableJson(previewFile,preview);
      received=await client.receiveSourceBundleBytes(dossierId,{questionId,bytes:capture.bundle,
        expectedBundleSha256:intent.bundleSha256,expectedRevision:preview.expectedRevision});
      need(received.id===dossierId&&Number.isSafeInteger(received.revision)&&received.revision>=baseRevision&&
        received.questions.some(question=>question.id===questionId),'PROTOCOL_NATIVE_RECEIVING_CHANGED');
      await protocolImmutableJson(join(root,'records','received.json'),received);
    }
    need(received.id===dossierId&&Number.isSafeInteger(received.revision)&&received.revision>=baseRevision,
      'PROTOCOL_RECEIVED_RECORD_CHANGED');
    const revision=received.revision;
    const savedBinding=await protocolOptional(join(root,'records','source-binding.json'),16*1024*1024);
    let binding;
    if(savedBinding){
      binding=JSON.parse(savedBinding.toString('utf8'));
    }else{
      const after=await client.previewSourceBundleBytes(dossierId,{questionId,bytes:capture.bundle});
      need(after.alreadyReceived===true&&after.bundleSha256===intent.bundleSha256&&
        typeof after.editionId==='string','PROTOCOL_NATIVE_EDITION_REQUIRED');
      const source=await client.source(dossierId,{editionId:after.editionId,key:'0',revision});
      binding={schema:STUDY_PROTOCOL_SCHEMA,workspaceId:expectedWorkspaceId,dossierId,questionId,revision,
        editionId:after.editionId,key:'0',bundleSha256:intent.bundleSha256,source};
      await protocolImmutableJson(join(root,'records','source-binding.json'),binding);
    }
    need(binding.workspaceId===expectedWorkspaceId&&binding.dossierId===dossierId&&
      binding.questionId===questionId&&binding.revision===revision&&binding.bundleSha256===intent.bundleSha256,
      'PROTOCOL_NATIVE_BINDING_CHANGED');
    const files=[];
    files.push(await exportFile(root,'source-bundle.json',file=>client.exportRetainedEdition(dossierId,binding.editionId,
      {file,revision,expectedSha256:intent.bundleSha256}),{expectedSha256:intent.bundleSha256}));
    for(const original of capture.inspected.value.files){
      files.push(await exportFile(root,'original-source/'+original.name,file=>client.exportSourceFile(dossierId,{
        file,revision,editionId:binding.editionId,key:'0',name:original.name,expectedSha256:original.sha256}),
        {expectedSha256:original.sha256}));
    }
    for(const [format,name]of [['json.gz','Research_Dossier.json.gz'],['html','Research_Report.html'],['md','Research_Report.md']]){
      files.push(await exportFile(root,name,file=>client.exportDossier(dossierId,{format,file,revision})));
    }
    files.push(...programmeFiles);
    for(const name of ['source-selection.json','CAPTURE_COMPLETE.json','source-manifest.json','source-bundle.json']){
      const bytes=await readResearchHostFile(join(resolve(captureDirectory),name),4*1024*1024);
      const target='original-source/'+name;await protocolImmutable(join(root,target),bytes);files.push(selectedFile(target,bytes));
    }
    await inspectStudyProtocolCapture(join(root,'original-source'));
    for(const name of ['baseline.json','received.json','source-binding.json']){
      const raw=await readResearchHostFile(join(root,'records',name),16*1024*1024);
      files.push(selectedFile('records/'+name,raw));
    }
    const selectedBytes=await readResearchHostFile(join(root,'receiving-selection.json'),1024*1024);
    files.push(selectedFile('receiving-selection.json',selectedBytes));
    const complete={schema:STUDY_PROTOCOL_SCHEMA,state:'RECEIVED_AND_EXPORTED',operation,
      workspaceId:expectedWorkspaceId,dossierId,questionId,baseRevision,revision,
      ...(programme.engineSelection?{engineSelection:programme.engineSelection}:{}),
      editionId:binding.editionId,key:binding.key,bundleSha256:intent.bundleSha256,
      protocol:capture.complete.protocol,registry:capture.complete.registry,files,
      portable:{file:'Research_Dossier.json.gz',receiver:'Original ResearchWorkspaceClient.reopenFile',
        expectedSha256:files.find(file=>file.file==='Research_Dossier.json.gz').sha256},
      sourceBindingFile:'records/source-binding.json',sourceIndex:'original-source/index.html'};
    await protocolImmutableJson(join(root,'RECEIVING_COMPLETE.json'),complete);
    return await inspectStudyProtocolReceiving(root);
  }finally{if(!providedClient)await client.close();}
}
